import React from "react";

const LEAF = "M0 0 C6 -7 17 -7 23 0 C17 7 6 7 0 0 Z";

/**
 * Stationery corner: twin acanthus scrolls meeting at a lotus, drawn for the top-left corner
 * in a 240×240 box. Mirror with scale(-1 1) / scale(1 -1) for the other corners.
 */
export const OrnateCorner: React.FC<{ size?: number; draw?: number }> = ({ size = 240, draw = 1 }) => {
  const dash = 700;
  return (
    <svg width={size} height={size} viewBox="0 0 240 240" style={{ overflow: "visible" }}>
      <g fill="none" stroke="url(#foil)" strokeLinecap="round" strokeDasharray={dash} strokeDashoffset={dash * (1 - draw)}>
        <path d="M14 232 C14 136 44 70 114 38 C146 24 186 16 232 14" strokeWidth={2.6} />
        <path d="M32 214 C32 146 62 100 112 78 C134 68 152 72 156 88 C160 102 146 112 134 106 C124 100 128 88 138 90" strokeWidth={2} />
        <path d="M214 32 C146 32 100 62 78 112 C68 134 72 152 88 156 C102 160 112 146 106 134 C100 124 88 128 90 138" strokeWidth={2} />
        <path d="M58 190 C66 160 84 140 104 128" strokeWidth={1.2} />
        <path d="M190 58 C160 66 140 84 128 104" strokeWidth={1.2} />
      </g>
      <g fill="url(#foil)" opacity={draw}>
        {/* lotus at the corner */}
        <path d="M44 44 C58 38 70 44 72 58 C58 60 48 56 44 44 Z" />
        <path d="M44 44 C38 58 44 70 58 72 C60 58 56 48 44 44 Z" />
        <path d="M44 44 C56 26 76 24 88 32 C74 38 58 42 44 44 Z" />
        <path d="M44 44 C26 56 24 76 32 88 C38 74 42 58 44 44 Z" />
        <circle cx={44} cy={44} r={6} />
        {/* leaves along the scrolls */}
        {[
          [30, 170, -70],
          [46, 120, -58],
          [80, 78, -40],
          [120, 44, -22],
          [170, 30, -12],
          [60, 206, -84],
        ].map(([x, y, r], i) => (
          <g key={i}>
            <path d={LEAF} transform={`translate(${x} ${y}) rotate(${r})`} />
            <path d={LEAF} transform={`translate(${y} ${x}) rotate(${-90 - r})`} />
          </g>
        ))}
        {[
          [92, 92, 3],
          [108, 60, 2],
          [60, 108, 2],
          [150, 36, 1.8],
          [36, 150, 1.8],
        ].map(([x, y, r], i) => (
          <circle key={i} cx={x} cy={y} r={r} />
        ))}
      </g>
    </svg>
  );
};

/** Four corners placed inside a frame of the given size. */
export const OrnateCorners: React.FC<{ width: number; height: number; inset?: number; size?: number; draw?: number }> = ({
  width,
  height,
  inset = 28,
  size = 240,
  draw = 1,
}) => {
  const place = (x: number, y: number, sx: number, sy: number) => (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: size,
        height: size,
        transform: `scale(${sx}, ${sy})`,
        transformOrigin: "center",
      }}
    >
      <OrnateCorner size={size} draw={draw} />
    </div>
  );
  return (
    <div style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
      {place(inset, inset, 1, 1)}
      {place(width - inset - size, inset, -1, 1)}
      {place(inset, height - inset - size, 1, -1)}
      {place(width - inset - size, height - inset - size, -1, -1)}
    </div>
  );
};
